const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "State of Developer Ecosystem 2024";
pres.author = "JetBrains";

// Color palette - Midnight Executive
const NAVY = "1E2761";
const ICE_BLUE = "CADCFC";
const WHITE = "FFFFFF";
const DARK_TEXT = "1E293B";
const MUTED_TEXT = "64748B";
const ACCENT_TEAL = "0891B2";
const ACCENT_GOLD = "F59E0B";
const LIGHT_BG = "F8FAFC";

// Slide 1: Title Slide
function createTitleSlide() {
  const slide = pres.addSlide();
  slide.background = { color: NAVY };

  // Decorative shape - large circle
  slide.addShape(pres.shapes.OVAL, {
    x: 7.5, y: -1.5, w: 5, h: 5,
    fill: { color: ICE_BLUE, transparency: 90 }
  });

  slide.addShape(pres.shapes.OVAL, {
    x: 8.5, y: 3.5, w: 3, h: 3,
    fill: { color: ICE_BLUE, transparency: 85 }
  });

  // Title
  slide.addText("State of Developer Ecosystem 2024", {
    x: 0.6, y: 1.6, w: 8.8, h: 1.2,
    fontSize: 36, fontFace: "Trebuchet MS", bold: true,
    color: WHITE, align: "left", valign: "middle"
  });

  // Subtitle
  slide.addText("Language Trends, Satisfaction, and Strategic Shifts", {
    x: 0.6, y: 2.8, w: 8.8, h: 0.6,
    fontSize: 20, fontFace: "Calibri",
    color: ICE_BLUE, align: "left"
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.5, w: 2.5, h: 0.05,
    fill: { color: ACCENT_TEAL }
  });

  // Source info
  slide.addText("Based on JetBrains survey of 23,262 developers worldwide", {
    x: 0.6, y: 3.8, w: 8.8, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: ICE_BLUE, align: "left"
  });

  // Bottom tag
  slide.addText("For Engineering Leaders, CTOs & Developer Experience Teams", {
    x: 0.6, y: 5.0, w: 8.8, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: MUTED_TEXT, align: "left"
  });
}

// Slide 2: Language Trends (Line Chart)
function createLanguageTrendsSlide() {
  const slide = pres.addSlide();
  slide.background = { color: WHITE };

  // Title
  slide.addText("Python Closes the Gap: 8 Years of Language Usage Shifts", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Trebuchet MS", bold: true,
    color: NAVY, align: "left", valign: "middle"
  });

  // Line chart - top 8 languages 2017-2024
  const chartData = [
    {
      name: "JavaScript",
      labels: ["2017", "2020", "2022", "2024"],
      values: [65, 70, 65, 61]
    },
    {
      name: "Python",
      labels: ["2017", "2020", "2022", "2024"],
      values: [32, 55, 53, 57]
    },
    {
      name: "HTML/CSS",
      labels: ["2017", "2020", "2022", "2024"],
      values: [60, 61, 54, 51]
    },
    {
      name: "SQL",
      labels: ["2017", "2020", "2022", "2024"],
      values: [42, 56, 49, 48]
    },
    {
      name: "Java",
      labels: ["2017", "2020", "2022", "2024"],
      values: [47, 54, 48, 46]
    },
    {
      name: "TypeScript",
      labels: ["2017", "2020", "2022", "2024"],
      values: [12, 28, 34, 37]
    },
    {
      name: "PHP",
      labels: ["2017", "2020", "2022", "2024"],
      values: [30, 27, 20, 17]
    },
    {
      name: "Rust",
      labels: ["2017", "2020", "2022", "2024"],
      values: [3, 7, 9, 11]
    }
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.5, y: 1.2, w: 6.8, h: 4.0,
    chartColors: ["F7C948", "0891B2", "64748B", "8B5CF6", "EF4444", "14B8A6", "F97316", "6366F1"],
    lineSmooth: true,
    lineSize: 2,
    showLegend: true,
    legendPos: "r",
    catAxisLabelColor: MUTED_TEXT,
    valAxisLabelColor: MUTED_TEXT,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: false,
    valAxisMaxVal: 80
  });

  // Key insights panel on right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.5, y: 1.2, w: 2.2, h: 4.0,
    fill: { color: LIGHT_BG }
  });

  slide.addText("Key Shifts", {
    x: 7.6, y: 1.3, w: 2.0, h: 0.4,
    fontSize: 14, fontFace: "Trebuchet MS", bold: true,
    color: NAVY
  });

  slide.addText([
    { text: "JavaScript peaked at 70% (2020), now 61%", options: { bullet: true, breakLine: true } },
    { text: "Python rose from 32% to 57%", options: { bullet: true, breakLine: true } },
    { text: "TypeScript tripled: 12% → 37%", options: { bullet: true, breakLine: true } },
    { text: "PHP dropped from 30% to 17%", options: { bullet: true, breakLine: true } },
    { text: "Rust grew from ~0 to 11%", options: { bullet: true } }
  ], {
    x: 7.6, y: 1.75, w: 2.0, h: 3.3,
    fontSize: 10, fontFace: "Calibri",
    color: DARK_TEXT, valign: "top"
  });
}

// Slide 3: Primary Language (Horizontal Bar)
function createPrimaryLanguageSlide() {
  const slide = pres.addSlide();
  slide.background = { color: WHITE };

  // Title
  slide.addText("Python Is Now the #1 Primary Language at 35%", {
    x: 0.5, y: 0.35, w: 9, h: 0.7,
    fontSize: 28, fontFace: "Trebuchet MS", bold: true,
    color: NAVY, align: "left", valign: "middle"
  });

  // Two-column layout
  // Left: Primary language bar chart
  const primaryData = [{
    name: "Developers",
    labels: ["Python", "Java", "JavaScript", "TypeScript", "SQL"],
    values: [35, 30, 28, 19, 17]
  }];

  slide.addChart(pres.charts.BAR, primaryData, {
    x: 0.5, y: 1.2, w: 4.5, h: 3.5,
    barDir: "bar",
    chartColors: ["0891B2"],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: DARK_TEXT,
    dataLabelFontSize: 11,
    catAxisLabelColor: MUTED_TEXT,
    valAxisLabelColor: MUTED_TEXT,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    valAxisMaxVal: 40
  });

  // Right: Adoption intent
  slide.addText("Adoption Intent", {
    x: 5.3, y: 1.2, w: 4.2, h: 0.4,
    fontSize: 16, fontFace: "Trebuchet MS", bold: true,
    color: NAVY
  });

  slide.addText("Only 4–6% of developers plan to adopt any new language", {
    x: 5.3, y: 1.6, w: 4.2, h: 0.4,
    fontSize: 11, fontFace: "Calibri",
    color: MUTED_TEXT
  });

  const adoptionData = [{
    name: "Plan to Adopt",
    labels: ["Python", "TypeScript", "Java", "SQL", "Go"],
    values: [6, 5, 4, 4, 3]
  }];

  slide.addChart(pres.charts.BAR, adoptionData, {
    x: 5.3, y: 2.1, w: 4.2, h: 2.2,
    barDir: "bar",
    chartColors: ["F59E0B"],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: DARK_TEXT,
    dataLabelFontSize: 10,
    catAxisLabelColor: MUTED_TEXT,
    valAxisLabelColor: MUTED_TEXT,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    valAxisMaxVal: 8
  });

  // Bottom insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.8, w: 9, h: 0.6,
    fill: { color: LIGHT_BG }
  });

  slide.addText("Ecosystem lock-in effect: Developers rarely switch primary languages, despite rising stars like Rust and Go", {
    x: 0.6, y: 4.85, w: 8.8, h: 0.5,
    fontSize: 12, fontFace: "Calibri", italic: true,
    color: DARK_TEXT, align: "center", valign: "middle"
  });
}

// Slide 4: Developer Satisfaction (Horizontal Bar Chart)
function createSatisfactionSlide() {
  const slide = pres.addSlide();
  slide.background = { color: WHITE };

  // Title
  slide.addText("TypeScript and Rust Top Developer Satisfaction", {
    x: 0.5, y: 0.35, w: 9, h: 0.65,
    fontSize: 28, fontFace: "Trebuchet MS", bold: true,
    color: NAVY, align: "left", valign: "middle"
  });

  // Subtitle
  slide.addText("Nearly tied at 199 vs 198 — reflecting enthusiasm for type safety and modern tooling", {
    x: 0.5, y: 0.95, w: 9, h: 0.35,
    fontSize: 13, fontFace: "Calibri",
    color: MUTED_TEXT
  });

  // Horizontal bar chart - satisfaction scores
  const satData = [{
    name: "Satisfaction Score",
    labels: ["TypeScript", "Rust", "Python", "Go", "Lua", "C++", "Kotlin", "Shell", "Dart", "C"],
    values: [199, 198, 151, 129, 118, 113, 113, 100, 93, 86]
  }];

  slide.addChart(pres.charts.BAR, satData, {
    x: 0.5, y: 1.4, w: 6.5, h: 3.9,
    barDir: "bar",
    chartColors: ["14B8A6"],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: DARK_TEXT,
    dataLabelFontSize: 11,
    catAxisLabelColor: DARK_TEXT,
    valAxisLabelColor: MUTED_TEXT,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    valAxisMaxVal: 220
  });

  // Right panel - insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 7.2, y: 1.4, w: 2.5, h: 3.9,
    fill: { color: NAVY }
  });

  slide.addText("Why TypeScript & Rust?", {
    x: 7.35, y: 1.55, w: 2.2, h: 0.5,
    fontSize: 13, fontFace: "Trebuchet MS", bold: true,
    color: WHITE
  });

  slide.addText([
    { text: "Type safety prevents bugs", options: { bullet: true, breakLine: true } },
    { text: "Modern tooling & DX", options: { bullet: true, breakLine: true } },
    { text: "Strong type systems", options: { bullet: true, breakLine: true } },
    { text: "Zero-cost abstractions (Rust)", options: { bullet: true, breakLine: true } },
    { text: "Memory safety guarantees", options: { bullet: true } }
  ], {
    x: 7.35, y: 2.1, w: 2.2, h: 3.0,
    fontSize: 11, fontFace: "Calibri",
    color: ICE_BLUE, valign: "top"
  });
}

// Slide 5: Domain Specialization (Table/Heatmap)
function createDomainSlide() {
  const slide = pres.addSlide();
  slide.background = { color: WHITE };

  // Title
  slide.addText("Each Language Owns a Domain", {
    x: 0.5, y: 0.35, w: 9, h: 0.65,
    fontSize: 28, fontFace: "Trebuchet MS", bold: true,
    color: NAVY, align: "left", valign: "middle"
  });

  // Subtitle
  slide.addText("AI belongs to Python, UI to TypeScript — language choice is driven by domain, not general preference", {
    x: 0.5, y: 0.95, w: 9, h: 0.35,
    fontSize: 13, fontFace: "Calibri",
    color: MUTED_TEXT
  });

  // Domain table
  const tableData = [
    [
      { text: "Domain", options: { fill: { color: NAVY }, color: WHITE, bold: true, align: "center" } },
      { text: "Leader", options: { fill: { color: NAVY }, color: WHITE, bold: true, align: "center" } },
      { text: "Share", options: { fill: { color: NAVY }, color: WHITE, bold: true, align: "center" } },
      { text: "Key Advantage", options: { fill: { color: NAVY }, color: WHITE, bold: true, align: "center" } }
    ],
    [
      { text: "AI / Machine Learning", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT } },
      { text: "Python", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT, bold: true } },
      { text: "31%", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT, align: "center" } },
      { text: "Rich ML ecosystem, TensorFlow, PyTorch", options: { fill: { color: LIGHT_BG }, color: MUTED_TEXT } }
    ],
    [
      { text: "User Interface", options: { fill: { color: WHITE }, color: DARK_TEXT } },
      { text: "TypeScript", options: { fill: { color: WHITE }, color: DARK_TEXT, bold: true } },
      { text: "62%", options: { fill: { color: WHITE }, color: DARK_TEXT, align: "center" } },
      { text: "React, Vue, Angular frameworks", options: { fill: { color: WHITE }, color: MUTED_TEXT } }
    ],
    [
      { text: "APIs & Services", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT } },
      { text: "Java", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT, bold: true } },
      { text: "49%", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT, align: "center" } },
      { text: "Spring Boot, mature enterprise stack", options: { fill: { color: LIGHT_BG }, color: MUTED_TEXT } }
    ],
    [
      { text: "System Tools & Components", options: { fill: { color: WHITE }, color: DARK_TEXT } },
      { text: "C++", options: { fill: { color: WHITE }, color: DARK_TEXT, bold: true } },
      { text: "27%", options: { fill: { color: WHITE }, color: DARK_TEXT, align: "center" } },
      { text: "Performance, hardware-level control", options: { fill: { color: WHITE }, color: MUTED_TEXT } }
    ],
    [
      { text: "Data Science & Analytics", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT } },
      { text: "Python", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT, bold: true } },
      { text: "28%", options: { fill: { color: LIGHT_BG }, color: DARK_TEXT, align: "center" } },
      { text: "Pandas, NumPy, Jupyter notebooks", options: { fill: { color: LIGHT_BG }, color: MUTED_TEXT } }
    ],
    [
      { text: "Data Processing", options: { fill: { color: WHITE }, color: DARK_TEXT } },
      { text: "Python", options: { fill: { color: WHITE }, color: DARK_TEXT, bold: true } },
      { text: "17%", options: { fill: { color: WHITE }, color: DARK_TEXT, align: "center" } },
      { text: "Pandas, Spark, ETL pipelines", options: { fill: { color: WHITE }, color: MUTED_TEXT } }
    ]
  ];

  slide.addTable(tableData, {
    x: 0.5, y: 1.45, w: 9, h: 3.8,
    colW: [2.4, 1.3, 0.9, 4.4],
    fontFace: "Calibri",
    fontSize: 12,
    border: { pt: 0.5, color: "E2E8F0" },
    valign: "middle"
  });
}

// Slide 6: Strategic Takeaways
function createTakeawaysSlide() {
  const slide = pres.addSlide();
  slide.background = { color: NAVY };

  // Title
  slide.addText("What This Means for Your Technology Strategy in 2025", {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fontSize: 26, fontFace: "Trebuchet MS", bold: true,
    color: WHITE, align: "left", valign: "middle"
  });

  // Divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 2, h: 0.04,
    fill: { color: ACCENT_TEAL }
  });

  // Strategic recommendations in 2x3 grid
  const recommendations = [
    { num: "1", title: "Invest in Python for AI/ML", desc: "Undisputed leader at 31% in AI/ML. Teams need Python expertise." },
    { num: "2", title: "TypeScript is the future of frontend", desc: "62% UI share, 37% overall. TypeScript skills are critical for modern web." },
    { num: "3", title: "Rust & Go are growth plays", desc: "Highest satisfaction scores and rising usage. Ideal for infrastructure." },
    { num: "4", title: "PHP & Ruby pools shrinking", desc: "PHP dropped 30%→17% since 2017. Ruby fell 10%→4%. Plan accordingly." },
    { num: "5", title: "Satisfaction = type safety + DX", desc: "TypeScript & Rust top satisfaction. Factor into developer retention." }
  ];

  const cardW = 2.9;
  const cardH = 1.25;
  const startX = 0.5;
  const startY = 1.4;
  const gapX = 0.15;
  const gapY = 0.15;

  recommendations.forEach((rec, i) => {
    const col = i % 3;
    const row = Math.floor(i / 3);
    const x = startX + col * (cardW + gapX);
    const y = startY + row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: cardH,
      fill: { color: ICE_BLUE, transparency: 85 }
    });

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: x + 0.1, y: y + 0.1, w: 0.35, h: 0.35,
      fill: { color: ACCENT_TEAL }
    });

    slide.addText(rec.num, {
      x: x + 0.1, y: y + 0.1, w: 0.35, h: 0.35,
      fontSize: 12, fontFace: "Calibri", bold: true,
      color: WHITE, align: "center", valign: "middle"
    });

    // Title
    slide.addText(rec.title, {
      x: x + 0.5, y: y + 0.1, w: cardW - 0.6, h: 0.4,
      fontSize: 12, fontFace: "Trebuchet MS", bold: true,
      color: WHITE, align: "left", valign: "middle"
    });

    // Description
    slide.addText(rec.desc, {
      x: x + 0.1, y: y + 0.55, w: cardW - 0.2, h: 0.6,
      fontSize: 10, fontFace: "Calibri",
      color: ICE_BLUE, align: "left", valign: "top"
    });
  });

  // Source footer
  slide.addText("Source: JetBrains State of Developer Ecosystem 2024 | 23,262 developers surveyed", {
    x: 0.5, y: 5.2, w: 9, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: MUTED_TEXT, align: "left"
  });
}

// Generate all slides
createTitleSlide();
createLanguageTrendsSlide();
createPrimaryLanguageSlide();
createSatisfactionSlide();
createDomainSlide();
createTakeawaysSlide();

pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Presentation saved to /app/output/final_deck.pptx"))
  .catch(err => console.error("Error:", err));

